package pl.zagranietyper.parser;import pl.zagranietyper.model.*;import java.text.Normalizer;import java.util.*;import java.util.regex.*;
public final class FootballTeamStatisticComparisonSyntaxAdapter {private static final Pattern MORE=Pattern.compile("^(.+?)(?: wykona| odda| popelni)? wiecej (rzutow roznych|roznych|strzalow celnych|celnych strzalow|strzalow|fauli)(?: od (.+))?$");private static final Pattern LESS=Pattern.compile("^(.+?)(?: wykona| odda| popelni)? mniej (rzutow roznych|roznych|strzalow celnych|celnych strzalow|strzalow|fauli)(?: od (.+))?$");private final FootballParticipantResolver resolver=new FootballParticipantResolver();public Result parse(String title,String home,String away){String n=norm(title);if(!(n.contains("wiecej")||n.contains("mniej"))||!statLike(n))return new Result(Status.NOT_LIKE,null);if(n.matches(".*[0-9].*")||n.contains(" i ")||n.contains(" oraz ")||n.contains(" + ")||n.contains("polow")||n.contains("handicap"))return new Result(Status.UNSUPPORTED,null);var m=MORE.matcher(n);var relation=FootballTeamStatisticComparisonCondition.Relation.MORE_THAN_OPPONENT;if(!m.matches()){m=LESS.matcher(n);relation=FootballTeamStatisticComparisonCondition.Relation.LESS_THAN_OPPONENT;}if(!m.matches())return new Result(Status.UNSUPPORTED,null);var selected=resolve(m.group(1),home,away);if(selected!=FootballParticipantResolver.Resolution.HOME&&selected!=FootballParticipantResolver.Resolution.AWAY)return new Result(Status.PARTICIPANT_UNRESOLVED,null);if(m.group(3)!=null){var opponent=resolve(m.group(3),home,away);if(selected==opponent||opponent==FootballParticipantResolver.Resolution.UNRESOLVED||opponent==FootballParticipantResolver.Resolution.AMBIGUOUS)return new Result(Status.PARTICIPANT_UNRESOLVED,null);}var side=selected==FootballParticipantResolver.Resolution.HOME?FootballFixtureStatisticsSnapshot.TeamSide.HOME:FootballFixtureStatisticsSnapshot.TeamSide.AWAY;return new Result(Status.PARSED,new FootballTeamStatisticComparisonCondition(type(m.group(2)),side,relation));}private FootballParticipantResolver.Resolution resolve(String s,String h,String a){return resolver.resolve(s,h,a,FootballParticipantResolver.MatchingPolicy.STRICT_SCORED_SUBSET,Map.of());}private static FootballFixtureStatisticType type(String s){if(s.contains("roz"))return FootballFixtureStatisticType.CORNERS;if(s.contains("celn"))return FootballFixtureStatisticType.SHOTS_ON_TARGET;if(s.contains("strzal"))return FootballFixtureStatisticType.SHOTS_TOTAL;return FootballFixtureStatisticType.FOULS;}private static boolean statLike(String n){return n.contains("rozn")||n.contains("strzal")||n.contains("faul");}private static String norm(String s){return Normalizer.normalize(s.replace('ł','l').replace('Ł','L'),Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).replaceAll("^[^\\p{L}\\p{N}]+","").replaceAll("[^\\p{L}\\p{N}+ ]+"," ").replaceAll("\\s+"," ").trim();}public enum Status{PARSED,NOT_LIKE,UNSUPPORTED,PARTICIPANT_UNRESOLVED}public record Result(Status status,FootballTeamStatisticComparisonCondition condition){public boolean parsed(){return status==Status.PARSED;}}}
